"""Query and serialize TOML values for the get command."""
import fnmatch
import json
import re
import sys
import datetime
from decimal import Decimal, InvalidOperation

from tomltest import _parse


class TemporalValue(str):
    """TOML date/time value that remains a bare token in TOML output."""


def _preserve_temporals(value, raw_values):
    if isinstance(value, dict):
        return {k: _preserve_temporals(v, raw_values) for k, v in value.items()}
    if isinstance(value, list):
        return [_preserve_temporals(v, raw_values) for v in value]
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return TemporalValue(raw_values.pop(0) if raw_values else value.isoformat())
    return value


def _path_parts(pattern):
    parts = []
    for part in re.findall(r"[^.\[\]]+|\[[^\]]*\]", pattern):
        if part.startswith("["):
            inside = part[1:-1]
            parts.append("*" if inside in ("", "*") else inside)
        else:
            parts.append(part)
    return parts


def _select(value, parts):
    if not parts:
        return [value]
    head, tail = parts[0], parts[1:]
    selected = []
    if isinstance(value, dict):
        for key, child in value.items():
            if head == "*" or fnmatch.fnmatchcase(str(key), head):
                selected.extend(_select(child, tail))
    elif isinstance(value, list):
        if head == "*":
            for child in value:
                selected.extend(_select(child, tail))
        else:
            try:
                index = int(head)
                if index < 0:
                    index += len(value)
                if 0 <= index < len(value):
                    selected.extend(_select(value[index], tail))
            except ValueError:
                pass
    return selected


def _toml_string(value):
    return json.dumps(value, ensure_ascii=False)


_DATE_TOKEN = re.compile(r"(?<![\w\"'])\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")


def _temporal(value, source):
    for match in _DATE_TOKEN.finditer(source):
        raw = match.group(0)
        try:
            if re.match(r"^\d{4}-", raw):
                candidate = (datetime.datetime.fromisoformat(raw.replace("Z", "+00:00").replace("z", "+00:00"))
                             if "T" in raw or "t" in raw or " " in raw else datetime.date.fromisoformat(raw))
            else:
                candidate = datetime.time.fromisoformat(raw)
            if candidate == value:
                return raw
        except ValueError:
            pass
    return value.isoformat()


def _toml(value, indent=0, source=""):
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _temporal(value, source)
    if isinstance(value, bool): return "true" if value else "false"
    if isinstance(value, TemporalValue): return str(value)
    if isinstance(value, str): return _toml_string(value)
    if value is None: return ""
    if isinstance(value, list): return "[ " + ", ".join(_toml(v, indent, source) for v in value) + " ]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{k} = {_toml(value[k], indent, source)}" for k in sorted(value)) + " }"
    return str(value)


def _is_inline_table(source, pattern):
    if not pattern:
        return False
    key = pattern.rsplit(".", 1)[-1]
    if not key.endswith("]") and re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*\{", source):
