"""Query and serialize TOML values for the get command."""
import fnmatch
import datetime
import json
import re
import sys
import datetime
from decimal import Decimal, InvalidOperation

from tomltest import _parse


class TemporalValue(str):
    """TOML date/time value that remains a bare token in TOML output."""


class FloatValue(str):
    """A floating point value retaining its TOML spelling."""


def _preserve_temporals(value, raw_values):
    if isinstance(value, dict):
        return {k: _preserve_temporals(v, raw_values) for k, v in value.items()}
    if isinstance(value, list):
        return [_preserve_temporals(v, raw_values) for v in value]
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        raw = raw_values.pop(0) if raw_values else value.isoformat()
        raw = re.sub(r"\.(\d+)", lambda m: ("." + m.group(1).rstrip("0")) if m.group(1).rstrip("0") else "", raw)
        return TemporalValue(raw)
    return value


def _float_spellings(source):
    # Mask strings and comments before looking for numeric tokens.
    chars = list(source)
    i = 0
    quote = None
    triple = False
    while i < len(chars):
        if quote is not None:
            if triple and source.startswith(quote * 3, i):
                chars[i:i + 3] = "   "
                i += 3
                quote = None
                triple = False
                continue
            c = source[i]
            chars[i] = " "
            if c == "\\" and quote == '"' and i + 1 < len(chars):
                chars[i + 1] = " "
                i += 2
                continue
            if not triple and c == quote:
                quote = None
            i += 1
            continue
        if source[i] == "#":
            while i < len(chars) and chars[i] != "\n":
                chars[i] = " "
                i += 1
            continue
        if source.startswith('"""', i) or source.startswith("'''", i):
            quote = source[i]
            triple = True
            chars[i:i + 3] = "   "
            i += 3
            continue
        if source[i] in "\"'":
            quote = source[i]
            chars[i] = " "
        i += 1
    masked = "".join(chars)
    temporal = re.compile(r"(?<![\w\"'])(?:\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")
    masked = temporal.sub(lambda match: " " * len(match.group(0)), masked)
    token_re = re.compile(r"(?<![\w.])[+-]?(?:\d(?:_?\d)*(?:\.\d(?:_?\d)*)?|\.\d(?:_?\d)*)(?:[eE][+-]?\d(?:_?\d)*)?(?![\w.])")
    found = {}
    for match in token_re.finditer(masked):
        raw = source[match.start():match.end()]
        if "." not in raw and "e" not in raw.lower():
            continue
        try:
            found.setdefault(repr(float(raw.replace("_", ""))), []).append(raw)
        except ValueError:
            pass
    return found


def _preserve_floats(value, spellings):
    if isinstance(value, dict):
        return {key: _preserve_floats(child, spellings) for key, child in value.items()}
    if isinstance(value, list):
        return [_preserve_floats(child, spellings) for child in value]
    if isinstance(value, float):
        queue = spellings.get(repr(value), [])
        return FloatValue(queue.pop(0)) if queue else value
    return value


def _path_parts(pattern):
    parts = []
    buf = []
    i = 0
    while i < len(pattern):
        char = pattern[i]
        if char in "\"'":
            quote = char
            start = i
            i += 1
            escaped = False
            while i < len(pattern):
                c = pattern[i]
                if escaped:
                    escaped = False
                elif c == "\\" and quote == '"':
                    escaped = True
                elif c == quote:
                    break
                i += 1
            token = pattern[start:i + 1]
            try:
                decoded = json.loads(token) if quote == '"' else token[1:-1]
            except Exception:
                decoded = token[1:-1]
            buf.append(decoded)
            i += 1
            continue
        if char == ".":
            if buf:
                parts.append("".join(buf)); buf = []
            i += 1
            continue
        if char == "[":
            if buf:
                parts.append("".join(buf)); buf = []
            end = pattern.find("]", i + 1)
            if end < 0:
                buf.append(pattern[i:]); break
            inside = pattern[i + 1:end]
            if len(inside) >= 2 and inside[0] == inside[-1] and inside[0] in "\"'":
                inside = inside[1:-1]
            parts.append("*" if inside in ("", "*") else inside)
            i = end + 1
            continue
        buf.append(char)
        i += 1
    if buf:
        parts.append("".join(buf))
    return parts


def _select(value, parts):
    if not parts:
        return [value]
    head, tail = parts[0], parts[1:]
    selected = []
    if isinstance(value, dict):
        for key, child in value.items():
            if head == "*" or fnmatch.fnmatchcase(str(key), head):
                selected.extend(_select(child, tail))
    elif isinstance(value, list):
        if head == "*":
            for child in value:
                selected.extend(_select(child, tail))
        else:
            try:
                index = int(head)
                if 0 <= index < len(value):
                    selected.extend(_select(value[index], tail))
            except ValueError:
                pass
    return selected


