def _temporal(value, source):
    for match in _DATE_TOKEN.finditer(source):
        raw = match.group(0)
        try:
            if re.match(r"^\d{4}-", raw):
                candidate = (datetime.datetime.fromisoformat(raw.replace("Z", "+00:00").replace("z", "+00:00"))
                             if "T" in raw or "t" in raw or " " in raw else datetime.date.fromisoformat(raw))
            else:
                candidate = datetime.time.fromisoformat(raw)
            if candidate == value:
                return raw
        except ValueError:
            pass
    return value.isoformat()


def _toml(value, indent=0, source=""):
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _temporal(value, source)

    if isinstance(value, bool): return "true" if value else "false"
    if isinstance(value, FloatValue): return str(value)
    if isinstance(value, TemporalValue): return str(value)
    if isinstance(value, datetime.datetime):
        return value.isoformat().replace("+00:00", "Z")
    if isinstance(value, (datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, str): return _toml_string(value)
    if value is None: return ""
    if isinstance(value, float) and hasattr(value, "spelling"):
        return value.spelling
    if isinstance(value, list): return "[ " + ", ".join(_toml(v, indent, source) for v in value) + " ]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{_toml_key(k)} = {_toml(v, indent, source)}" for k, v in value.items()) + " }"
    return str(value)



def _inline_root(source, key):
    return re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*(?:\{|\[\s*\{)", source) is not None


def _toml_document(document, source=""):
    """Serialize a complete document, retaining insertion order and table form."""
    chunks = []
    root_values = [(k, v) for k, v in document.items() if not isinstance(v, dict)
                   and not (isinstance(v, list) and v and all(isinstance(x, dict) for x in v))
                   or _inline_root(source, k)]
    if root_values:
        chunks.append("\n".join(f"{_toml_key(k)} = {_toml(v)}" for k, v in root_values))

    def emit_table(name, table):
        lines = [f"[{name}]"] if name else []
        children = []
        for key, value in table.items():
            if isinstance(value, dict):
                children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value):
                children.append((key, value))
            else:
                lines.append(f"{_toml_key(key)} = {_toml(value)}")
        if lines:
            chunks.append("\n".join(lines))
        for key, value in children:
            path = f"{name}.{key}" if name else key
            if isinstance(value, list):
                for table_item in value:
                    emit_array_table(path, table_item)
            else:
                emit_table(path, value)

    def emit_array_table(name, table):
        lines = [f"[[{name}]]"]
        children = []
        for key, value in table.items():
            if isinstance(value, dict): children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value): children.append((key, value))
            else: lines.append(f"{_toml_key(key)} = {_toml(value)}")
        chunks.append("\n".join(lines))
        for key, value in children:
            path = f"{name}.{key}"
            if isinstance(value, list):
                for item in value: emit_array_table(path, item)
            else: emit_table(path, value)

    for key, value in document.items():
        if isinstance(value, dict) and not _inline_root(source, key): emit_table(key, value)
        elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value) and not _inline_root(source, key):
            for item in value: emit_array_table(key, item)
    return "\n".join(chunks) + ("\n" if chunks else "")



def _is_inline_table(source, pattern):
    if not pattern:
        return False
    parts = _path_parts(pattern)
    key = parts[-1] if parts else pattern
    if not key.endswith("]") and re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*\{", source):
        return True
    # A table selected by array index retains inline-table formatting when
    # its containing value was written as an inline array of tables.
    for index, part in enumerate(parts):
        if part.isdigit() and index:
            parent = parts[index - 1]
            if re.search(r"(?m)^\s*" + re.escape(parent) + r"\s*=\s*\[[^\n]*\{", source):
                return True
    return False


def _table_document(value, source, base_parts=(), relative_headers=True):
    """Serialize a selected document/table while retaining explicit tables."""
    if not isinstance(value, dict):
        return _toml(value) + "\n"
    lines = []
    child_tables = []
    arrays_of_tables = []
    for key, child in value.items():
        path = tuple(base_parts) + (str(key),)
        dotted = ".".join(path)
        table_header = re.search(r"(?m)^\s*\[\s*" + re.escape(dotted) + r"\s*\]\s*(?:#.*)?$", source)
        array_header = re.search(r"(?m)^\s*\[\[\s*" + re.escape(dotted) + r"\s*\]\]\s*(?:#.*)?$", source)
        if isinstance(child, dict) and table_header:
            child_tables.append((key, child, path))
        elif isinstance(child, list) and child and all(isinstance(x, dict) for x in child) and array_header:
            arrays_of_tables.append((key, child, path))
        else:
            lines.append(f"{_toml_key(key)} = {_toml(child)}")
    for key, child, path in child_tables:
        suffix = ".".join(path[len(base_parts):] if relative_headers else path)
        header = f"[{suffix}]"
        if lines and re.search(r"=\s*\{.*\}$", lines[-1]):
            lines[-1] += header
        else:
            lines.append(header)
        lines.extend(_table_document(child, source, path, relative_headers).rstrip("\n").splitlines())
    for key, children, path in arrays_of_tables:
        suffix = ".".join(path[len(base_parts):] if relative_headers else path)
        for child in children:
            lines.append(f"[[{suffix}]]")
            lines.extend(_table_document(child, source, path, relative_headers).rstrip("\n").splitlines())
    inline_keys = [key for key, child in value.items() if isinstance(child, dict) and _inline_root(source, str(key))]
    if lines and len(inline_keys) == len(value) and inline_keys:
        return "".join(lines) + "\n"
    return "\n".join(lines) + ("\n" if lines else "")


