def _normalize_json_exponents(text):
    """Match serde_json's compact exponent spelling without touching strings."""
    out = []
    i = 0
    in_string = False
    escaped = False
    number = re.compile(r"-?\d+(?:\.\d+)?[eE][+-]?\d+")
    while i < len(text):
        char = text[i]
        if in_string:
            out.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            i += 1
        elif char == '"':
            in_string = True
            out.append(char)
            i += 1
        elif char == "-" or char.isdigit():
            match = number.match(text, i)
            if match:
                token = match.group(0)
                token = re.sub(r"[eE]\+?(-?)0*(\d+)$", r"e\1\2", token)
                out.append(token)
                i = match.end()
            else:
                out.append(char)
                i += 1
        else:
            out.append(char)
            i += 1
    return "".join(out)


